package com.bananalab.lite;
import android.content.*;import java.io.*;import java.util.*;import org.json.*;
/** Portable approved source/spec journal. Private app data and baked APK assets are distinct layers. */
final class DurableCode{
 static volatile String status="";static volatile java.util.concurrent.CountDownLatch ready=new java.util.concurrent.CountDownLatch(0);
 static void awaitReady()throws Exception{if(!ready.await(120,java.util.concurrent.TimeUnit.SECONDS))throw new IOException("La recuperación inicial sigue en curso. Reintentá el pedido.");}
 static final int PORTABLE_LIMIT=33554432;
 static final String[] KINDS={"animacion","chat","acciones","planificador"};
 static SharedPreferences prefs(Context c){return c.getSharedPreferences("banana-durable-code",0);}
 static JSONObject portable(Context c)throws Exception{return portable(c,true);}
 static JSONObject portable(Context c,boolean knowledge)throws Exception{JSONObject active=new JSONObject(ProjectRuntime.prefs(c).getString("active","{}")),modules=new JSONObject();for(String kind:KINDS)if(active.has(kind)){JSONObject row=active.getJSONObject(kind);ProjectRuntime.verify(c,row);modules.put(kind,new JSONObject().put("spec",row.getJSONObject("spec")).put("sources",new JSONObject(ProjectReplacementSpec.sources(c,row.getJSONObject("spec")))).put("sourceHash",row.getString("sourceHash")));}JSONObject experience=new JSONObject().put("model",PlannerExperience.prefs(c).getString("model","")).put("cases",PlannerExperience.prefs(c).getString("cases","[]")).put("auto",PlannerExperience.prefs(c).getBoolean("auto",true)).put("style",MobileCore.prefs(c).getString("style","normal"));JSONObject result=new JSONObject().put("version",4).put("evolution",SelfLearning.portable(c)).put("chatEdits",ChatEdits.portable(c)).put("modules",modules).put("experience",experience).put("methodExperience",MethodLab.experience(c)).put("readingTraining",ReadingTraining.portable(c)).put("continuousLearning",LearningLoop.portable(c));if(knowledge)result.put("knowledge",KnowledgeNotebook.data(c));if(result.toString().getBytes("UTF-8").length>PORTABLE_LIMIT)throw new IOException("El respaldo supera32MiB; exportá menos contenido antes de incorporarlo");return result;}
 static void validate(Context c,JSONObject data)throws Exception{if(data.optInt("version")==4){RuntimeProgram.keys(data,"version","modules","experience","methodExperience","chatEdits","evolution","knowledge","readingTraining","continuousLearning");if(data.has("continuousLearning"))LearningLoop.validate(data.getJSONObject("continuousLearning"));if(data.has("readingTraining"))ReadingTraining.validate(data.getJSONObject("readingTraining"));SelfLearning.validate(data.getJSONObject("evolution"));if(data.has("knowledge"))KnowledgeNotebook.validate(data.getJSONArray("knowledge"));ChatEdits.validate(data.getJSONObject("chatEdits"));MethodLab.validateExperience(data.getJSONObject("methodExperience"));}else if(data.optInt("version")==3){RuntimeProgram.keys(data,"version","modules","experience","methodExperience","chatEdits");ChatEdits.validate(data.getJSONObject("chatEdits"));MethodLab.validateExperience(data.getJSONObject("methodExperience"));}else if(data.optInt("version")==2){RuntimeProgram.keys(data,"version","modules","experience","methodExperience");MethodLab.validateExperience(data.getJSONObject("methodExperience"));}else RuntimeProgram.keys(data,"version","modules","experience");if(data.getInt("version")!=1&&data.getInt("version")!=2&&data.getInt("version")!=3&&data.getInt("version")!=4)throw new IOException("Formato de código desconocido.");JSONObject modules=data.getJSONObject("modules");if(modules.length()>4)throw new IOException("Demasiados módulos.");Iterator<String> keys=modules.keys();while(keys.hasNext()){String kind=keys.next();if(!Arrays.asList(KINDS).contains(kind))throw new IOException("Destino de módulo desconocido.");JSONObject row=modules.getJSONObject(kind),spec=row.getJSONObject("spec");RuntimeProgram.keys(row,"spec","sources","sourceHash");if(!kind.equals(spec.getString("kind")))throw new IOException("Destino de módulo incorrecto.");String sources=new JSONObject(ProjectReplacementSpec.sources(c,spec)).toString();if(!sources.equals(row.getJSONObject("sources").toString())||!JavaMethodEditor.hash(sources).equals(row.getString("sourceHash")))throw new IOException("La fuente portable no coincide con su contrato.");}JSONObject experience=data.getJSONObject("experience");RuntimeProgram.keys(experience,"model","cases","auto","style");if(experience.has("style")&&!experience.getString("style").matches("normal|breve|detallado"))throw new IOException("Estilo no válido");JSONArray cases=new JSONArray(experience.getString("cases"));if(cases.length()>32)throw new IOException("Demasiados casos aprendidos.");for(int i=0;i<cases.length();i++){JSONObject x=cases.getJSONObject(i);RuntimeProgram.keys(x,"input","rulesHash","label","source");if(!x.getString("source").equals("user")||x.getString("input").length()>600||!x.getString("rulesHash").matches("[a-f0-9]{64}")||!x.getString("label").matches("[a-z0-9_]{0,24}"))throw new IOException("Caso de aprendizaje inválido.");}String model=experience.getString("model");if(!model.isEmpty()){JSONObject m=new JSONObject(model);if(!m.getString("rulesHash").matches("[a-f0-9]{64}"))throw new IOException("Modelo sin identidad.");int n=m.getJSONArray("weights").length();if(n<1||n>8)throw new IOException("Modelo fuera de límites.");PlannerExperience.weights(m,n);}}
 static JSONObject row(Context c,JSONObject spec,File jar)throws Exception{return new JSONObject().put("spec",spec).put("jar",jar.getAbsolutePath()).put("jarHash",ProjectRuntime.digest(jar)).put("sourceHash",JavaMethodEditor.hash(new JSONObject(ProjectReplacementSpec.sources(c,spec)).toString())).put("tests",ProjectReplacementSpec.samples(spec)).put("appBase",JavaProject.fingerprint(c));}
 static void experience(Context c,JSONObject data)throws Exception{if(data.has("continuousLearning"))LearningLoop.restore(c,data.getJSONObject("continuousLearning"));if(data.has("readingTraining"))ReadingTraining.restore(c,data.getJSONObject("readingTraining"));if(data.has("knowledge"))KnowledgeNotebook.restore(c,data.getJSONArray("knowledge"));JSONObject e=data.getJSONObject("experience");if(e.has("style")&&!MobileCore.prefs(c).contains("style")&&!MobileCore.prefs(c).edit().putString("style",e.getString("style")).commit())throw new IOException("No pude restaurar el estilo");if(!PlannerExperience.prefs(c).contains("model")&&!PlannerExperience.prefs(c).contains("cases")){if(!PlannerExperience.prefs(c).edit().putString("model",e.getString("model")).putString("cases",e.getString("cases")).putBoolean("auto",e.getBoolean("auto")).commit())throw new IOException("No pude recuperar el aprendizaje incluido.");PlannerExperience.restore(c);}if(data.optInt("version")>=2)MethodLab.importExperience(c,data.getJSONObject("methodExperience"));if(data.optInt("version")>=3)ChatEdits.restore(c,data.getJSONObject("chatEdits"));if(data.optInt("version")==4)SelfLearning.importPortable(c,data.getJSONObject("evolution"));}
 static synchronized String importBackup(Context c,JSONObject data)throws Exception{validate(c,data);String prior=ProjectRuntime.prefs(c).getString("active","{}");JSONObject modules=new JSONObject(),all=data.getJSONObject("modules");for(String kind:KINDS)if(all.has(kind)){JSONObject spec=all.getJSONObject(kind).getJSONObject("spec");OnDeviceJava.Build build=OnDeviceJava.compileSources(c,ProjectReplacementSpec.sources(c,spec));JavaTrial.request(c,build.jar,spec.toString(),"project",ProjectReplacementSpec.samples(spec));modules.put(kind,row(c,spec,build.jar));}ProjectRuntime.Snapshot next=ProjectRuntime.load(c,modules,true);synchronized(ProjectRuntime.class){if(!prior.equals(ProjectRuntime.prefs(c).getString("active","{}")))throw new IOException("La versión activa cambió durante la importación.");ProjectRuntime.commit(c,modules,next,ProjectRuntime.archive(c));}experience(c,data);return "Código portable recompilado, probado y activado. El aprendizaje local existente tiene prioridad sobre el respaldo.";}
 static void bootstrap(Context c)throws Exception{NotebookArchive.bootstrap(c);JSONObject data;try{data=new JSONObject(AppJavaChat.asset(c,"banana-code/manifest.json",PORTABLE_LIMIT));}catch(FileNotFoundException absent){return;}validate(c,data);if(data.has("continuousLearning"))LearningLoop.restore(c,data.getJSONObject("continuousLearning"));if(data.has("readingTraining"))ReadingTraining.restore(c,data.getJSONObject("readingTraining"));if(data.has("knowledge"))KnowledgeNotebook.restore(c,data.getJSONArray("knowledge"));if(data.optInt("version")>=3)ChatEdits.restore(c,data.getJSONObject("chatEdits"));if(data.optInt("version")==4)SelfLearning.importPortable(c,data.getJSONObject("evolution"));synchronized(ProjectRuntime.class){if(ProjectRuntime.prefs(c).contains("active"))return;}JSONObject modules=new JSONObject(),all=data.getJSONObject("modules");for(String kind:KINDS)if(all.has(kind)){JSONObject spec=all.getJSONObject(kind).getJSONObject("spec");String expected=AppJavaChat.asset(c,"banana-code/"+kind+".sha256",100).trim();if(!expected.matches("[a-f0-9]{64}"))throw new IOException("Identidad de módulo embebido inválida.");File target=new File(OnDeviceJava.home(c),"embedded-"+expected+".jar");if(!target.exists())try(InputStream in=c.getAssets().open("banana-code/"+kind+".jar")){OnDeviceJava.immutable(target,OnDeviceJava.bytes(in,1000000));}if(!ProjectRuntime.digest(target).equals(expected))throw new IOException("El módulo incluido cambió.");modules.put(kind,row(c,spec,target));}ProjectRuntime.Snapshot next=ProjectRuntime.load(c,modules,true);synchronized(ProjectRuntime.class){if(ProjectRuntime.prefs(c).contains("active"))return;ProjectRuntime.commit(c,modules,next,new JSONArray());}experience(c,data);status="Cargué el código compilado incluido dentro de esta APK.";}
 static void revalidate(Context c)throws Exception{if(ProjectRuntime.error.isEmpty())return;String prior=ProjectRuntime.prefs(c).getString("active","{}");JSONObject old=new JSONObject(prior),modules=new JSONObject();for(String kind:KINDS)if(old.has(kind)){JSONObject previous=old.getJSONObject(kind);File jar=new File(previous.getString("jar"));if(!jar.getCanonicalPath().startsWith(OnDeviceJava.home(c).getCanonicalPath()+File.separator)||!ProjectRuntime.digest(jar).equals(previous.getString("jarHash")))throw new IOException("Un archivo activo cambió; queda pendiente de revisión.");JSONObject spec=previous.getJSONObject("spec");OnDeviceJava.Build built=OnDeviceJava.compileSources(c,ProjectReplacementSpec.sources(c,spec));JavaTrial.request(c,built.jar,spec.toString(),"project",ProjectReplacementSpec.samples(spec));modules.put(kind,row(c,spec,built.jar));}ProjectRuntime.Snapshot next=ProjectRuntime.load(c,modules,true);synchronized(ProjectRuntime.class){if(!prior.equals(ProjectRuntime.prefs(c).getString("active","{}")))return;ProjectRuntime.commit(c,modules,next,ProjectRuntime.archive(c));}status="Recompilé y probé los módulos conservados contra esta versión de Banana.";}
 static void start(final Context context){final Context c=context.getApplicationContext();final java.util.concurrent.CountDownLatch completion=new java.util.concurrent.CountDownLatch(1);ready=completion;new Thread(new Runnable(){public void run(){try{CoreBuild.sync(c);bootstrap(c);revalidate(c);}catch(Exception e){status="Conservé el registro, pero falta revisar compatibilidad: "+AndroidRepair.summary(e);}finally{completion.countDown();}}},"banana-durable-restore").start();}
 static File exportBackup(Context c)throws Exception{File folder=c.getDir("apk-build",0),file=new File(folder,"Banana-codigo-"+UUID.randomUUID()+".json");OnDeviceJava.immutable(file,portable(c).toString().getBytes("UTF-8"));prefs(c).edit().putString("export",file.getAbsolutePath()).commit();return file;}
 static BananaEngine.Result handle(Context c,String input)throws Exception{String q=ChatLanguage.normalize(input);if(!q.matches("codigo permanente|estado codigo permanente|importa firma privada|olvida firma privada|exporta mi codigo|importa mi codigo|reconstruye mi apk|reconstrui mi apk"))return null;try{if(q.equals("importa firma privada"))return MobileCore.say(c,"Elegí tu archivo privado de actualización. No es otra APK ni otra app; se configura una vez.","code_import_key");if(q.equals("importa mi codigo"))return MobileCore.say(c,"Elegí un respaldo de código de Banana. Se validará y recompilará antes de activarse.","code_import_backup");if(q.equals("olvida firma privada")){if(!ApkSigning.prefs(c).edit().clear().commit())throw new IOException("No pude retirar la firma.");return MobileCore.say(c,"Retiré la firma importada. Las APK generadas nunca la incluyen.","app_ajuste");}if(q.equals("exporta mi codigo")){exportBackup(c);return MobileCore.say(c,"Preparé las fuentes canónicas aprobadas y el aprendizaje para guardarlos.","code_export_backup");}if(q.startsWith("reconstr")){JavaChat.owner=Thread.currentThread();try{File built=DeviceApk.build(c);prefs(c).edit().putString("export",built.getAbsolutePath()).commit();return MobileCore.say(c,"Preparé Banana.apk, la actualización normal de esta misma app, con todo Java recompilado, pesos entrenados activos, módulos y aprendizaje. Guardala y abrila para confirmar la actualización de Android.","code_export_apk");}finally{JavaChat.owner=null;JavaChat.progress="";}}return MobileCore.say(c,"Código permanente\nFirma importada: "+ApkSigning.prefs(c).contains("sealed")+"\n"+status+"\nLos módulos activos viven en datos privados y sobreviven a actualizaciones compatibles.\nPara incluirlos físicamente en una APK: importa firma privada → reconstruye mi apk.\nRespaldo: exporta mi codigo / importa mi codigo.\nEl paquete recompila todo Java, convierte las lambdas admitidas y genera un DEX nuevo. Los recursos empaquetados se conservan. Cambios coordinados de ABI son posibles si todo el proyecto compila. No modifica silenciosamente la APK instalada. Las actualizaciones del núcleo conservan el registro y vuelven a comprobar compatibilidad.","app_ajuste");}catch(Exception e){return MobileCore.say(c,"No cambié el código instalado: "+AndroidRepair.summary(e),"app_ajuste");}}
}
